import { sha256 } from '../core/receipt.a41219b99c47.mjs';
export function createProjectSwitcherModel({projects=[]}={}){let list=projects.map(p=>({available:true,trusted:false,...p,id:String(p.id)})).sort((a,b)=>Number(b.trusted)-Number(a.trusted)||Number(b.lastOpenedAt??0)-Number(a.lastOpenedAt??0));let cursor=-1;return Object.freeze({snapshot:()=>Object.freeze({projects:Object.freeze(list.map(Object.freeze)),cursor}),select(id){const p=list.find(x=>x.id===String(id));if(!p)throw new Error('Unknown project');if(!p.available)throw new Error('Project root is unavailable');const base={schema:'nolane.ui.project-switch.v1',projectId:p.id,path:p.path,selectedAt:new Date(0).toISOString()};return Object.freeze({...base,receiptSha256:sha256(JSON.stringify(base))})},move(delta=1){if(!list.some(p=>p.available))throw new Error('No available project');do{cursor=(cursor+Number(delta)+list.length)%list.length}while(!list[cursor].available);return list[cursor]}})}
